function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const count = new Map();
  for (const ch of s) count.set(ch, (count.get(ch) || 0) + 1);
  for (const ch of t) {
    const c = (count.get(ch) || 0) - 1;
    if (c < 0) return false;
    count.set(ch, c);
  }
  for (const v of count.values()) if (v !== 0) return false;
  return true;
}

