#include <unordered_map>
#include <string>
bool isAnagram(const std::string& s, const std::string& t) {
  if (s.size() != t.size()) return false;
  std::unordered_map<char, int> cnt;
  for (char c : s) ++cnt[c];
  for (char c : t) {
    if (--cnt[c] < 0) return false;
  }
  for (auto& p : cnt) if (p.second != 0) return false;
  return true;
}

